module TopModule (
    input  wire        clk,
    input  wire        load,
    input  wire [255:0] data,
    output reg  [255:0] q
);

    // Helper function to get the value of a cell at (row, col) with toroidal wrapping
    function automatic logic get_cell(input [7:0] row, input [7:0] col);
        // Wrap row and col to [0,15] using modulo 16 (bitwise AND with 15)
        logic [3:0] r = row & 4'hF;
        logic [3:0] c = col & 4'hF;
        // Index = r * 16 + c
        return q[r * 16 + c];
    endfunction

    // Next state register
    reg [255:0] q_next;

    // Sequential logic: update state on positive clock edge
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= q_next;
        end
    end

    // Combinational logic: compute next state
    always @* begin
        q_next = 256'b0;
        for (int i = 0; i < 16; i++) begin
            for (int j = 0; j < 16; j++) begin
                // Count live neighbors
                int count = 0;
                // Iterate over the 3x3 neighborhood centered at (i,j), excluding self
                for (int di = -1; di <= 1; di++) begin
                    for (int dj = -1; dj <= 1; dj++) begin
                        if (di == 0 && dj == 0) begin
                            continue; // Skip self
                        end
                        count = count + get_cell(i + di, j + dj);
                    end
                end

                // Apply game rules
                if (count == 2) begin
                    // State does not change
                    q_next[i*16 + j] = q[i*16 + j];
                end else if (count == 3) begin
                    // Cell becomes alive
                    q_next[i*16 + j] = 1'b1;
                end else begin
                    // 0-1 or 4+ neighbors: cell becomes dead
                    q_next[i*16 + j] = 1'b0;
                end
            end
        end
    end

endmodule

