module TopModule (
    input clk,
    input areset,
    input predict_valid,
    input [6:0] predict_pc,
    output predict_taken,
    output [6:0] predict_history,
    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history,
    input [6:0] train_pc
);

    // 7-bit global history register
    reg [6:0] ghr;

    // Pattern History Table: 128 entries, each a 2-bit saturating counter
    reg [1:0] pht [0:127];

    // Internal signals
    wire [6:0] predict_index = predict_pc ^ ghr;
    wire [6:0] train_index = train_pc ^ train_history;

    // Prediction logic: taken if counter >= 2 (i.e., 2'b10 or 2'b11)
    assign predict_taken = (pht[predict_index] >= 2'b10);
    assign predict_history = ghr;

    // Next state for GHR
    reg [6:0] ghr_next;

    // Combinational logic for GHR next state
    always @(*) begin
        // Default: no change
        ghr_next = ghr;

        if (train_valid) begin
            if (train_mispredicted) begin
                // On misprediction, recover GHR to the state after the branch
                // train_history is the GHR before the branch, so after branch:
                // shift left by 1, insert train_taken as LSB
                ghr_next = {train_history[5:0], train_taken};
            end else begin
                // Correct prediction: update GHR with actual outcome
                ghr_next = {ghr[5:0], train_taken};
            end
        end else if (predict_valid) begin
            // On prediction (and no training), update GHR with predicted outcome
            ghr_next = {ghr[5:0], predict_taken};
        end
        // If neither, ghr_next remains ghr (held)
    end

    // Sequential logic for GHR and PHT updates
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
            // Initialize PHT to weakly not taken (2'b01) for all entries
            integer i;
            for (i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b01;
            end
        end else begin
            ghr <= ghr_next;

            // PHT update: only on training, and only if not mispredicted?
            // According to spec: on training, update PHT to train the branch predictor.
            // Misprediction flag is for history recovery, not to skip PHT update.
            // We update PHT on every train_valid, regardless of mispredicted.
            if (train_valid) begin
                // Update the 2-bit saturating counter based on train_taken
                if (train_taken) begin
                    // If not already strongly taken, increment
                    if (pht[train_index] != 2'b11) begin
                        pht[train_index] <= pht[train_index] + 2'b01;
                    end
                end else begin
                    // If not already strongly not taken, decrement
                    if (pht[train_index] != 2'b00) begin
                        pht[train_index] <= pht[train_index] - 2'b01;
                    end
                end
            end
            // Note: if both predict and train occur on same index, PHT read (for predict)
            // happens in this cycle before update (which is next cycle), so correct per spec.
        end
    end

endmodule
